CREATE   VIEW [Product_Portfolio].[vw_MON_Item_Values_Pivoted] AS

	SELECT *
	FROM (
		SELECT 
		 item_id
		,board_id
		,column_title
		,column_value
		FROM 
		MondaydotCom.ItemValues
		WHERE board_id <> 1150004587
		) AS Calcifer
	PIVOT(
		MAX(column_value)
		FOR column_title IN (
			 [1 Member/Non-Member]
			,[2 Member/Non-Member]
			,[2023 Product catalogue]
			,[3 Member/Non Member]
			,[4 Member/Non Member]
			,[5 Member/Non Member]
			,[Actual On Sale Date]
			,[Added to FinOps]
			,[Booking platform]
			,[Country]
			,[Create sub-items]
			,[CSAT score]
			,[Delivery Lead]
			,[Departmental owner]
			,[E Learning Specialist]
			,[End Date]
			,[End Time]
			,[EV Code if applicable]
			,[EventBrite link]
			,[Feedback Link]
			,[Format]
			,[Hosting]
			,[Language]
			,[Lead time (days on sale)]
			,[Length (Hours/Days)]
			,[link to Standards and Markets Webinar Requests]
			,[Local Time for Host]
			,[Marketing Owner]
			,[Member Engagement Planner 2024]
			,[Member Engagement Planner 2025]
			,[Member Price]
			,[Move to member engagement board]
			,[Non-Member Price]
			,[Numbers Attended]
			,[Numbers Booked]
			,[Off Demand]
			,[OLA Link]
			,[On demand?]
			,[On sale days early/late]
			,[On sale on time?]
			,[Online / F2F]
			,[PB complete date]
			,[PB days early/late]
			,[PB Due date (calculated)]
			,[PB on time?]
			,[PC Specialist]
			,[PD Lead]
			,[Percentage attended]
			,[Platform/Venue]
			,[Product brief]
			,[Product Folder]
			,[Product Group dropdown]
			,[Product opportunity analysis]
			,[Product opportunity form]
			,[Production end date]
			,[Production start date]
			,[Professional Group]
			,[Project Manager]
			,[Project size]
			,[Region]
			,[rics.org Link]
			,[Send to OLA board]
			,[SKU Code]
			,[SKU creation date]
			,[Speaker 1 Email Address]
			,[Speaker 1 Name]
			,[Speaker 2 Email Address]
			,[Speaker 2 Name]
			,[Speaker 3 Email Address]
			,[Speaker 3 Name]
			,[Speaker 4]
			,[Speaker 4 Email]
			,[Speaker 5]
			,[Speaker 5 Email]
			,[Stage]
			,[Start Date]
			,[Start Time]
			,[Sub-format]
			,[Subitems]
			,[Suggested month]
			,[Suggested quarter]
			,[Tags]
			,[Target on sale date (calculated)]
			,[Year]
			,[Annual Event Name]
		)
	) AS Pivoted
	;
